def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    df['island'] = df['island'].replace('Bisco', 'Biscoe')
    df['sex'] = df['sex'].astype(str).str.strip()
    df.loc[df['sex'] == 'nan', 'sex'] = float('nan')
    for col in ['flipper_length_mm', 'body_mass_g', 'year']:
        df[col] = pd.to_numeric(df[col], errors='coerce')
    return df

def answer(df):
    df = clean(df)
    grouped = df.groupby('species')['body_mass_g'].sum()
    return {str(k): int(v) if float(v).is_integer() else float(v) for k, v in grouped.items() if pd.notna(k)}
